<?php require 'functions.php';$items=load_data('carriers');if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$items=array_filter($items,fn($x)=>(int)$x['id']!==$id);save_data('carriers',$items);redirect('carriers.php','Transportador excluído.');}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$row=['id'=>$id?:next_id($items),'name'=>trim($_POST['name']),'document'=>trim($_POST['document']),'phone'=>trim($_POST['phone']),'vehicle'=>trim($_POST['vehicle']),'plate'=>strtoupper(trim($_POST['plate']))];if($id){foreach($items as &$x){if((int)$x['id']===$id){$x=$row;break;}}}else{$items[]=$row;}save_data('carriers',$items);redirect('carriers.php',$id?'Transportador atualizado.':'Transportador cadastrado.');}$edit=isset($_GET['edit'])?find_by_id($items,(int)$_GET['edit']):null;$title='Transportadores';require 'header.php';?>
<h2 class="page-title">Transportadores</h2><div class="row g-4"><div class="col-lg-4"><div class="card p-4"><h5><?=$edit?'Editar':'Novo'?> transportador</h5><form method="post"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label class="form-label">Nome/Razão social</label><input required class="form-control mb-2" name="name" value="<?=h($edit['name']??'')?>"><label class="form-label">CPF/CNPJ</label><input class="form-control mb-2" name="document" value="<?=h($edit['document']??'')?>"><label class="form-label">Telefone</label><input class="form-control mb-2" name="phone" value="<?=h($edit['phone']??'')?>"><label class="form-label">Veículo</label><input class="form-control mb-2" name="vehicle" value="<?=h($edit['vehicle']??'')?>"><label class="form-label">Placa</label><input class="form-control mb-3" name="plate" value="<?=h($edit['plate']??'')?>"><button class="btn btn-primary w-100">Salvar</button></form></div></div><div class="col-lg-8"><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Nome</th><th>Veículo</th><th>Placa</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=$x['id']?></td><td><?=h($x['name'])?></td><td><?=h($x['vehicle'])?></td><td><?=h($x['plate'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$x['id']?>">Editar</a> <a onclick="return confirm('Excluir?')" class="btn btn-sm btn-outline-danger" href="?delete=<?=$x['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require 'footer.php';?>
